using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
using RainbowLi;
using RainbowLi.UnityGame;
public static class BattlePlaybackChecks {
 static double started;static int stage,checks,events,beforeEvents,eventFrame,frameEvents,maximumBudget;static float began,frozen;static GameView v;static Vector3 position;static string expected;static int expectedEvents;
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);checks++;}
 static void Next(int n){stage=n;began=Time.unscaledTime;}
 public static void Run(){try{
  RainbowLi.EditorTools.BattlePlaybackSceneMigration.Run();RainbowLi.EditorTools.BattlePlaybackSceneMigration.ApplyCurrent();
  v=UnityEngine.Object.FindFirstObjectByType<GameView>();Check(v.battlePanel.GetComponentsInChildren<BattlePlaybackView>(true).Length==1,"migration idempotent");var ui=v.battlePanel.GetComponentInChildren<BattlePlaybackView>(true);Check(ui.skip.onClick.GetPersistentMethodName(0)=="Skip"&&ui.speed.onClick.GetPersistentMethodName(0)=="CycleSpeed","native button wiring");
  var c=new BattlePlaybackClock();Check(Mathf.Abs(c.Tick(1,.1f,true,1)-.1f)<.001f,"1x clock");Check(c.Tick(1,.1f,true,4)==.1f,"one tick per frame");Check(c.Tick(2,.5f,false,4)==.1f,"pause clock");Check(Mathf.Abs(c.Tick(3,.1f,true,2)-.3f)<.001f,"2x clock");Check(Mathf.Abs(c.Tick(4,.1f,true,4)-.7f)<.001f,"4x clock");c.Reset();Check(c.Tick(5,0,true,1)==0,"reset clock");
  started=EditorApplication.timeSinceStartup;Application.logMessageReceived+=Log;EditorApplication.update+=Tick;EditorSettings.enterPlayModeOptionsEnabled=true;EditorSettings.enterPlayModeOptions=EnterPlayModeOptions.DisableDomainReload;EditorApplication.EnterPlaymode();
 }catch(Exception e){Fail(e);}}
 static void Log(string s,string stack,LogType t){if(stack.Contains("UnityEditor.Search.SearchDatabase"))return;if(t==LogType.Error||t==LogType.Exception)Fail(new Exception(s+stack));}
 static string State(ContainmentGame g)=>g.Phase+"|"+g.Round+"|"+g.Health+"|"+g.EnemyHealth+"|"+g.Shield+"|"+g.EnemyShield+"|"+g.Power+"|"+g.EnemyPower+"|"+g.Coins+"|"+g.Hand.Count+"|"+g.DiscardCards.Count+"|"+string.Join(",",Enumerable.Range(0,26).Select(i=>g.Player.Statuses[(CardEffect)i]+":"+g.Enemy.Statuses[(CardEffect)i]));
 static void Setup(bool lethal=false){v.session.seed=314159;v.session.NewGame();var g=v.session.Game;g.StartBattle();g.EnemyHealth=lethal?1:500;g.EnemyMaxHealth=500;g.EnemyShield=0;var c=g.Hand[0];c.Spec=null;c.Effect=CardEffect.Strike;c.AttackBase=15;c.BaseBonus=0;g.InsertCard(c,0);v.session.Notify();}
 static void SetupChant(){Setup();var g=v.session.Game;g.Timeline.RemoveAll(a=>!a.Enemy);g.PlayerRules.Clear();g.EnemyRule.Numbers=new[]{0,0,0};foreach(var rule in g.ArenaRules)rule.Numbers=new[]{0,0,0};var r=g.ArenaRules[0];r.Numbers=new[]{2,2,2};r.Effect=RuleEffect.Power;r.Value=0;r.InsertsTwo=false;r.AdditionalEffect=new SequenceEffect{Effect=RuleEffect.Power,Value=0};foreach(var a in g.Timeline){a.Effect=CardEffect.Guard;a.Value=0;a.Number=5;}for(int i=0;i<3;i++){g.Hand[i].Spec=null;g.Hand[i].Effect=CardEffect.Guard;g.Hand[i].Number=2;g.InsertCard(g.Hand[i],i);}g.Player.Statuses.Add(CardEffect.Chant,200);v.session.Notify();}
 static void Tick(){try{
  if(EditorApplication.timeSinceStartup-started>120)throw new Exception("timeout stage "+stage);if(!EditorApplication.isPlaying)return;v=UnityEngine.Object.FindFirstObjectByType<GameView>();if(v==null||!v.IsReady)return;var b=v.battle;var m=v.cardMotion;var fx=m.effects;var g=v.session.Game;
  if(stage==0){v.session.Resolved+=e=>{events++;if(eventFrame!=Time.frameCount){eventFrame=Time.frameCount;frameEvents=0;}maximumBudget=Math.Max(maximumBudget,++frameEvents);};b.autoPlay=false;Setup();Check(m.ActiveTransfers>0,"planning draw/placement active");Next(1);return;}
  if(stage==1){if(b.HasPresentation)return;Check(!b.IsPresentationPaused,"planning flights finish with autoplay off");b.Confirm();Check(g.Phase==GamePhase.Resolving&&b.IsPresentationPaused,"confirm paused does not run");frozen=b.PresentationTime;beforeEvents=events;Next(2);return;}
  if(stage==2){if(Time.unscaledTime-began<.3f)return;Check(b.PresentationTime==frozen&&events==beforeEvents,"pause freezes clock and simulation");var ui=v.battlePanel.GetComponentInChildren<BattlePlaybackView>();Canvas.ForceUpdateCanvases();Check(ui.stateLabel.gameObject.activeInHierarchy&&ui.stateLabel.text.Contains("已暂停"),"pause status visible");Check(ui.stateLabel.cachedTextGenerator.vertexCount>0,"status generates visible text geometry");b.Step();b.Step();Check(b.IsStepping&&!b.autoPlay,"single step started once");Next(3);return;}
  if(stage==3){if(b.IsStepping)return;Check(events==beforeEvents+1,"one and only one event per single step");Check(!b.HasPresentation&&b.IsPresentationPaused,"single step drains impact particles then pauses");Check(v.enemyHealth.value==g.EnemyHealth,"health applied at hit");Capture();beforeEvents=events;b.ToggleAutoPlay();Next(4);return;}
  if(stage==4){if(m.ActiveCasts==0)return;b.ToggleAutoPlay();Check(b.IsPresentationPaused,"pause during cast");frozen=b.PresentationTime;var ghost=m.motionLayer.Find("FlyingCard");position=ghost==null?Vector3.zero:ghost.localPosition;Next(5);return;}
  if(stage==5){if(Time.unscaledTime-began<.35f)return;Check(b.PresentationTime==frozen,"active cast clock frozen");var ghost=m.motionLayer.Find("FlyingCard");Check(ghost==null||Vector3.Distance(position,ghost.localPosition)<.001f,"flying card frozen");b.SetSpeed(2);Check(b.PlaybackSpeed==2,"exact user 2x");b.SetSpeed(4);Check(b.PlaybackSpeed==4,"exact user 4x");b.TrackResolution(new ResolutionEvent{Action=new BattleAction{},Round=g.Round});for(int i=0;i<10;i++)b.TrackResolution(new ResolutionEvent{Action=new BattleAction{IsRepeat=true},Round=g.Round});Check(b.RepeatSpeed==2,"repeat acceleration shared multiplier");b.TrackResolution(new ResolutionEvent{Action=new BattleAction{},Round=g.Round});Check(b.RepeatSpeed==1,"ordinary effect resets repeat acceleration");b.ToggleAutoPlay();Next(6);return;}
  if(stage==6){if(fx.ActiveBursts==0)return;b.ToggleAutoPlay();frozen=b.PresentationTime;position=fx.shakeRoot.localPosition;beforeEvents=events;Next(7);return;}
  if(stage==7){if(Time.unscaledTime-began<.3f)return;Check(b.PresentationTime==frozen&&events==beforeEvents,"impact pause freezes resolution");Check(Vector3.Distance(position,fx.shakeRoot.localPosition)<.001f,"shake frozen");b.Skip();Check(b.IsSkipping,"skip started from pause");Check(m.ActiveCasts==0&&m.ActiveTransfers==0&&fx.ActiveBursts==0,"skip clears live visual queue");Next(8);return;}
  if(stage==8){if(b.IsSkipping)return;Check(g.Phase!=GamePhase.Resolving&&!b.HasPresentation,"skip drains round and leaves no visuals");Check(m.motionLayer.childCount==0,"no skip ghosts");
   b.SetSpeed(1);Setup();g=v.session.Game;Check(g.Confirm(),"baseline confirm");int count=0;while(g.Phase==GamePhase.Resolving&&count<5000){if(g.Step())count++;}Check(g.Phase!=GamePhase.Resolving,"baseline terminal");expected=State(g);expectedEvents=count;Setup();g=v.session.Game;b.Confirm();beforeEvents=events;b.Skip();Next(9);return;}
  if(stage==9){if(b.IsSkipping)return;Check(State(g)==expected,"skip result equals ordinary rule execution");Check(events-beforeEvents==expectedEvents,"skip preserves every real event");Check(!b.HasPresentation&&m.motionLayer.childCount==0,"skip suppression prevents new ghosts");
   Setup();g=v.session.Game;b.Confirm();m.ClearDesignerPreview();m.PreviewAttack(40,6);Check(m.ActiveCasts>0,"designer preview plays while paused");Next(10);return;}
  if(stage==10){if(b.HasPresentation)return;Check(b.IsPresentationPaused,"designer preview returns to pause");m.PreviewAttack(40,6);b.Step();v.session.NewGame();Check(!b.IsStepping&&!b.IsSkipping&&b.RepeatedEffects==0&&!b.HasPresentation,"restart clears pending steps and visual state");Check(fx.comboLabel.text==""&&fx.shakeRoot.localPosition==Vector3.zero,"restart clears combo and shake");
   b.autoPlay=false;Setup(true);g=v.session.Game;b.Confirm();b.Step();Next(12);return;}
  
  if(stage==12){if(g.Phase!=GamePhase.Reward)return;Check(m.KeepBattleVisible&&v.battlePanel.activeSelf&&!v.rewardPanel.activeSelf,"lethal event holds battle UI");Next(13);return;}
  if(stage==13){if(b.HasPresentation||b.IsStepping)return;Check(v.rewardPanel.activeSelf&&!v.battlePanel.activeSelf,"reward after final feedback drained");Check(m.motionLayer.childCount==0&&fx.ActiveBursts==0,"last effect cleanup");
   Setup();g=v.session.Game;b.Confirm();b.Skip();v.session.NewGame();Check(!b.IsSkipping&&!b.HasPresentation,"restart cancels skip");Check(Time.timeScale==1,"global UI clock unaffected");SetupChant();g=v.session.Game;Check(g.Confirm(),"long chant baseline confirm");int count=0;while(g.Phase==GamePhase.Resolving&&count<5000){if(g.Step())count++;}Check(count>200,"long chant really executes over 200 events");expected=State(g);expectedEvents=count;SetupChant();b.Confirm();beforeEvents=events;maximumBudget=0;frameEvents=0;b.Skip();Next(14);return;}
  if(stage==14){if(b.IsSkipping)return;Check(State(g)==expected&&events-beforeEvents==expectedEvents,"long chant skip equals normal execution");Check(maximumBudget<=32,"long skip bounded to 32 events per frame");Check(!b.HasPresentation,"long skip leaves no queue");Console.WriteLine("PASS: "+checks+" battle playback, pause, step, speed, skip equivalence, long chains, preview and lifecycle checks.");EditorApplication.update-=Tick;EditorApplication.Exit(0);}
 }catch(Exception e){Fail(e);}}
 static void Capture(){
  if(SystemInfo.graphicsDeviceType==UnityEngine.Rendering.GraphicsDeviceType.Null)return;
  var canvas=v.GetComponent<Canvas>();var mode=canvas.renderMode;var camera=UnityEngine.Object.FindFirstObjectByType<Camera>();var oldTarget=camera.targetTexture;var oldActive=RenderTexture.active;
  var rt=new RenderTexture(1920,1080,24);var image=new Texture2D(1920,1080,TextureFormat.RGB24,false);
  try{camera.targetTexture=rt;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=rt;image.ReadPixels(new Rect(0,0,1920,1080),0,0);image.Apply();System.IO.Directory.CreateDirectory("Assets/RainbowLi/Verification~/PlaybackPreview");System.IO.File.WriteAllBytes("Assets/RainbowLi/Verification~/PlaybackPreview/01-paused.png",image.EncodeToPNG());}
  finally{RenderTexture.active=oldActive;camera.targetTexture=oldTarget;canvas.renderMode=mode;UnityEngine.Object.DestroyImmediate(image);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}
 }
 static void Fail(Exception e){Console.WriteLine("PLAYBACK FAILED: "+e);EditorApplication.Exit(1);}
}
